WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, attr_key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) e AS attr_key, attr_value), flattened_carts AS (SELECT id, customer_id, created_at, attr_key, attr_value, EXPLODE(coupon_codes) AS element FROM flattened), filtered AS (SELECT id, customer_id, created_at, attr_key, attr_value, element, UPPER(attr_key) AS attr_key_upper, CONCAT_WS(',', attr_key, element) AS attr_key_element_key, COALESCE(attr_key, 'NONE') AS resolved_attr_key FROM flattened_carts WHERE attr_key IN ('gift', 'device')), valid AS (SELECT *, HOUR(created_at) AS created_at_hour, LENGTH(element) AS element_length, COALESCE(attr_key, 'NONE') AS attr_key_filled FROM filtered WHERE attr_key IS DISTINCT FROM 'gift'), metrics AS (SELECT *, MIN(created_at_hour) OVER w_recent AS element_min_created_at_hour, MIN(created_at_hour) OVER w_recent AS element_min_created_at_hour_2 FROM valid WINDOW w_recent AS (PARTITION BY element)), scored AS (SELECT *, COUNT(created_at_hour) OVER (ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS created_at_hour_count_30m, STDDEV_SAMP(element_length) OVER (PARTITION BY customer_id, attr_key) AS customer_id_stddev_samp_element_length, AVG(element_min_created_at_hour_2) OVER (PARTITION BY attr_key) AS attr_key_avg_element_min_created_at_hour_2, MAX(element_min_created_at_hour_2) OVER (PARTITION BY attr_key ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS element_min_created_at_hour_2_max_15m FROM metrics), joined AS (SELECT e.*, b.city, b.segment, b.name FROM scored e JOIN customers b ON e.customer_id = b.id) SELECT p.country, src.element, COUNT(*) AS num_rows, ROUND(AVG(src.element_min_created_at_hour_2_max_15m), 2) AS avg_element_min_created_at_hour_2_max_15m, ROUND(AVG(src.attr_key_avg_element_min_created_at_hour_2), 2) AS avg_attr_key_avg_element_min_created_at_hour_2 FROM joined src JOIN customers p ON src.customer_id = p.id GROUP BY GROUPING SETS ((p.country, src.element), (p.country)) ORDER BY avg_element_min_created_at_hour_2_max_15m DESC NULLS LAST
